class Status(Enum):
    authorized = 'authorized'
    pending = 'pending'
    expired = 'expired'
    revoked = 'revoked'
    not_required = 'not_required'
    unknown = 'unknown'


class ReferenceAuthorization(AdCPBaseModel):
    model_config = ConfigDict(
        extra='allow',
    )
    status: Annotated[
        Status,
        Field(
            description='Current seller-observed authorization state. `authorized`: seller can serve the referenced post. `pending`: additional creator/account action is required. `expired` or `revoked`: authorization previously existed but no longer permits serving. `not_required`: the seller can legally and technically serve without a separate identity authorization. `unknown`: seller has not checked or cannot disclose the state.'
        ),
    ]
    checked_at: Annotated[
        AwareDatetime | None,
        Field(description='When the seller last checked the authorization state.'),
    ] = None
    expires_at: Annotated[
        AwareDatetime | None,
        Field(description='When the authorization expires, if the platform exposes an expiry.'),
    ] = None
    authorization_url: Annotated[
        AnyUrl | None,
        Field(description='Optional URL the buyer or creator can use to complete authorization.'),
    ] = None
    authorization_instructions: Annotated[
        str | None,
        Field(description='Human-readable instructions for completing or restoring authorization.'),
    ] = None


